#define NOB_IMPLEMENTATION
#include "nob.h"

int main(int argc, char *argv[])
{
        GO_REBUILD_URSELF(argc, argv);

        Cmd cmd = {0};
        cmd_append(&cmd,

                   // Compile with all warning
                           "cc", "-Wall", "-Wextra",

                   // Suppress the warnings generated by the default arguments
                   // technique
                           "-Wno-override-init", "-Wno-initializer-overrides",

                   // C Standard
                           "-std=c99",

                   // Output File
                           "-o", "server.obj",

                   // Include Directories
                           "-I./thirdparty",

                   // Translation Units
                           "src/main.c",
                           "src/request.c",
                           "src/response.c"
                   );

        if (!cmd_run(&cmd)) {
                nob_log(ERROR, "Failed to build.");
                return 1;
        }

        cmd.count = 0;

        cmd_append(&cmd, "./server.obj");

        return cmd_run(&cmd);
}
